UPDATE products SET description='اتركي زحمة اليوم، وابدئي بلحظة انتعاش. غسول أرينسيا بقوام الموتشي يتحوّل مع الماء إلى رغوة تساعد على إزالة الشوائب اليومية والزيوت الزائدة، ويترك البشرة بإحساس نظيف وناعم لتكملي روتينكِ براحة.',details_json='{"nameAr":"غسول أرينسيا غرين رايس موتشي","tagline":"لحظة نقاء، على مهلكِ.","benefits":["يساعد على إزالة الشوائب والزيوت الزائدة","قوام موتشي يتحوّل مع الماء إلى رغوة","يترك البشرة بإحساس نظيف وناعم بعد الشطف"],"howToUse":"خذي كمية صغيرة وامزجيها بالماء بين يديكِ لتكوين رغوة. دلّكي البشرة الرطبة بلطف، ثم اشطفي جيدًا بماء فاتر وأكملي بالمرطّب المناسب لكِ.","notes":"جرّبي على منطقة صغيرة أولًا، وتوقفي عند التهيّج. تجنبي العينين والجلد المجروح والفرك القوي. راجعي مكونات العبوة للحساسية؛ القوائم الرسمية تتضمن العطر ومكوّنًا مشتقًا من اللوز. اتبعي تعليمات عبوتكِ.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"cleanser","en":{"name":"Arencia Fresh Green Rice Mochi Cleanser","tagline":"A fresh start. A moment for you.","description":"Let the day slow down with a fresh little ritual. Arencia’s mochi-like cleanser lathers with water to help wash away daily impurities and excess oil, leaving skin feeling clean and soft.","benefits":["Helps wash away daily impurities and excess oil","Mochi-like paste that lathers with water","Leaves skin feeling clean and soft after rinsing"],"howToUse":"Work a small amount with water into a lather. Massage gently onto damp skin, then rinse thoroughly with lukewarm water and follow with your preferred moisturiser.","notes":"Patch test and stop if irritation occurs. Avoid eyes, broken skin and harsh rubbing. Check the jar for allergies; official lists include fragrance and an almond-derived ingredient. Follow your jar’s directions.","variantNote":"","size":"120 g"},"contentVersion":"3.2.0","size":"120 غرام"}',updated_at=datetime('now') WHERE id='TS0098' AND description='أغلقي يومكِ بلحظة انتعاش. امنحي روتين الغسل ملمسًا مختلفًا مع غسول الموتشي من أرينسيا. يركز على إزالة شوائب السطح وترك إحساس بالنظافة، ويليق بمن تحب تحويل التنظيف اليومي إلى لحظة عناية أكثر اهتمامًا بالتفاصيل.' AND details_json='{"nameAr":"غسول غرين رايس موتشي من أرينسيا","tagline":"تنظيف بقوام يضيف متعة إلى العناية.","benefits":["تنظيف الشوائب اليومية","قوام موتشي مميز","تكملة لروتين النعومة"],"howToUse":"اتبعي طريقة أخذ الكمية وترطيب الوجه والتدليك ثم الشطف المدونة على العبوة.","notes":"تجنبي الفرك القوي ومحيط العينين، وأكملي الترطيب بعد الغسل.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"cleanser","en":{"name":"Arencia - Fresh Green Rice Mochi Cleanser","tagline":"A fresh start, or a gentle end to your day.","description":"Arencia - Fresh Green Rice Mochi Cleanser. A fresh start, or a gentle end to your day. Make cleansing the first step of a little time for yourself.","benefits":["A fresh start, or a gentle end to your day.","A dedicated step to coordinate with your existing routine."],"howToUse":"Follow the instructions for this cleanser’s format. Massage gently without rubbing hard, and rinse or wipe off as its label directs.","notes":"Avoid contact with the eyes unless the exact product is labelled for eye makeup removal. Patch test and stop if irritation occurs.","variantNote":""},"contentVersion":"3.0.0"}';
INSERT INTO promotions(id,kind,title,description,config_json,active) SELECT 'PROMOARENCIA-PAIR','offer','ثنائي أرينسيا: لحظتان من الانتعاش','عبوتان من غسول غرين رايس موتشي، 120 غرام لكل عبوة. سعر العبوتين 19.99 دينار مع التوصيل المجاني.','{"id":"PROMOARENCIA-PAIR","kind":"offer","active":true,"title":"ثنائي أرينسيا: لحظتان من الانتعاش","description":"عبوتان من غسول غرين رايس موتشي، 120 غرام لكل عبوة. سعر العبوتين 19.99 دينار مع التوصيل المجاني.","items":[{"id":"TS0098","qty":2}],"priceFils":19990,"en":{"title":"Arencia: the two-jar ritual","description":"Two Fresh Green Rice Mochi Cleanser jars, 120 g each. The pair is 19.99 JOD with free delivery."}}',1 WHERE EXISTS (SELECT 1 FROM products WHERE id='TS0098' AND active=1 AND approved=1 AND price_fils=11000) ON CONFLICT(id) DO NOTHING;
